/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn rewrite_spread_item(
    &mut self,
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    // Find the `**` token preceding the spread.
    let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
        .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

    if let Some(last) = dict.iter_values().last() {
        // Ex) `**{a: 1, b: 2}` or `**({a: 1, b: 2})`
        self.begin_spread_rewrite();

        // Delete the `**` and any parentheses wrapping the dict, up to and
        // including the dict's opening brace.
        let mut open_brace_removed = false;
        for tok in
            SimpleTokenizer::starts_at(doublestar.end(), locator.contents()).skip_trivia()
        {
            match tok.kind() {
                SimpleTokenKind::LParen => {
                    self.push_spread_deletion(tok.range());
                }
                SimpleTokenKind::LBrace => {
                    self.push_spread_deletion(tok.range());
                    open_brace_removed = true;
                    break;
                }
                _ => return None,
            }
        }
        if !open_brace_removed {
            return None;
        }

        // Delete the last item's trailing comma, the dict's closing brace,
        // and any parentheses closing the dict, while preserving any
        // intervening trivia.
        let mut close_brace_removed = false;
        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
            if close_brace_removed {
                if tok.kind() == SimpleTokenKind::RParen {
                    self.push_spread_deletion(tok.range());
                } else {
                    break;
                }
            } else {
                match tok.kind() {
                    SimpleTokenKind::Comma => {
                        self.push_spread_deletion(tok.range());
                    }
                    SimpleTokenKind::RBrace => {
                        self.push_spread_deletion(tok.range());
                        close_brace_removed = true;
                    }
                    _ => return None,
                }
            }
        }
        if !close_brace_removed {
            return None;
        }

        Some(Fix::safe_edits(
            // Delete the first `**`
            Edit::deletion(doublestar.start(), doublestar.end()),
            self.take_spread_edits(),
        ))
    } else {
        // Ex) `**{}`
        Some(Fix::safe_edit(Edit::deletion(
            doublestar.start(),
            dict.end(),
        )))
    }
}

